#!/usr/bin/env python3
"""
Refresh `unicode-names.txt` — the vendored name table the Unicode composer
dataset is generated from.

    python3 scripts/vendor/refresh-unicode-names.py

Why a vendored file rather than an npm dependency: the only npm packages that
carry Unicode character names carry ALL of them (~155,000 rows, hundreds of
megabytes unpacked) for the ~3,400 this feature curates. Python's `unicodedata`
ships with every macOS and Linux box, is offline, and is the same table the
spec's measurements were taken against — so the vendoring step is thirty lines
and the output is a reviewable text file.

The output is COMMITTED and is a generator input only. It never reaches the
runtime bundle; `scripts/generate-unicode-index.ts` is its only consumer.

⚠ This file decides WHICH BLOCKS exist. Everything else — which categories are
dropped, the emoji dedupe, the LaTeX aliases — is decided in the TypeScript
generator, where it can be reviewed alongside the code that uses it.

Refreshing against a newer Unicode version changes search results, which makes
it a `v2` dataset plus a corpus regeneration, never an in-place `v1` edit. See
`lib/char-insert/README.md`.
"""

import sys
import unicodedata
from pathlib import Path

# The 26 curated blocks, in code-point order. Slugs match
# `UNICODE_BLOCK_LABELS` in `lib/char-insert/profiles/unicode.ts`; the generator
# asserts the two agree, so a block added here without a label fails loudly.
#
# Everything absent is absent for a reason recorded in the spec: CJK/Hangul and
# the other algorithmically-named ranges (~110,000 characters a name search
# cannot rank), historic scripts, and Mathematical Alphanumeric Symbols (~1,000
# near-identical names that would add noise to every `\a…` query).
BLOCKS = [
    ("latin-1-supplement", 0x0080, 0x00FF),
    ("latin-extended-a", 0x0100, 0x017F),
    ("latin-extended-b", 0x0180, 0x024F),
    ("ipa-extensions", 0x0250, 0x02AF),
    ("spacing-modifier-letters", 0x02B0, 0x02FF),
    ("greek-and-coptic", 0x0370, 0x03FF),
    ("cyrillic", 0x0400, 0x04FF),
    ("general-punctuation", 0x2000, 0x206F),
    ("superscripts-and-subscripts", 0x2070, 0x209F),
    ("currency-symbols", 0x20A0, 0x20CF),
    ("letterlike-symbols", 0x2100, 0x214F),
    ("number-forms", 0x2150, 0x218F),
    ("arrows", 0x2190, 0x21FF),
    ("mathematical-operators", 0x2200, 0x22FF),
    ("miscellaneous-technical", 0x2300, 0x23FF),
    ("box-drawing", 0x2500, 0x257F),
    ("block-elements", 0x2580, 0x259F),
    ("geometric-shapes", 0x25A0, 0x25FF),
    ("miscellaneous-symbols", 0x2600, 0x26FF),
    ("dingbats", 0x2700, 0x27BF),
    ("misc-math-symbols-a", 0x27C0, 0x27EF),
    ("supplemental-arrows-a", 0x27F0, 0x27FF),
    ("supplemental-arrows-b", 0x2900, 0x297F),
    ("misc-math-symbols-b", 0x2980, 0x29FF),
    ("supplemental-math-operators", 0x2A00, 0x2AFF),
    ("misc-symbols-and-arrows", 0x2B00, 0x2BFF),
]

OUT_PATH = Path(__file__).with_name("unicode-names.txt")


def main() -> int:
    lines = [
        "# Generated by scripts/vendor/refresh-unicode-names.py — do not hand-edit.",
        f"# Unicode {unicodedata.unidata_version}, {len(BLOCKS)} curated blocks.",
        "# Format: HEX;NAME;GENERAL_CATEGORY;BLOCK_SLUG",
    ]

    for slug, low, high in BLOCKS:
        for code_point in range(low, high + 1):
            char = chr(code_point)
            try:
                name = unicodedata.name(char)
            except ValueError:
                # Unassigned, or a control character with no name. Nothing to
                # insert either way.
                continue
            lines.append(
                f"{code_point:04X};{name};{unicodedata.category(char)};{slug}"
            )

    OUT_PATH.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"Wrote {len(lines) - 3} rows to {OUT_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
